<?php require_once 'bootstrap.php';$u=require_login();$s=db()->prepare('SELECT * FROM bookings WHERE user_id=? ORDER BY created_at DESC');$s->execute([$u['id']]);$bookings=$s->fetchAll();$pageTitle='My Account | PC World Geek';require 'header.php';?><main class="page"><div class="wrap"><span class="eyebrow">MY ACCOUNT</span><h1>Hello, <?=e($u['name'])?>.</h1><p class="pagelead">Manage your support requests and start a new booking.</p><div class="account-actions"><a class="btn primary" href="booking.php">Book Support</a><a class="btn ghost" href="remote-support.php">Start Remote Support</a><a class="btn ghost" href="logout.php">Log Out</a></div><h2>Your bookings</h2><div class="tablewrap"><table><tr><th>Service</th><th>Date</th><th>Time</th><th>Status</th></tr><?php foreach($bookings as $b):?><tr><td><?=e($b['service'])?></td><td><?=e($b['preferred_date'])?></td><td><?=e($b['preferred_time'])?></td><td><?=e($b['status'])?></td></tr><?php endforeach;?></table></div></div></main><?php require 'footer.php';?>